class Solution {
    public: int visiblePoints(vector<vector<int>>& points,int angle,vector<int>& location){
        if(angle>=360)return points.size();
        vector<double> angles;
        int same=0;
        for(auto& point:points){
            int dx=point[0]-location[0],dy=point[1]-location[1];
            if(!dx&&!dy)++same;
            else angles.push_back(atan2(dy,dx));
        }
        sort(angles.begin(),angles.end());
        int original=angles.size();
        for(int i=0;i<original;++i)angles.push_back(angles[i]+2*M_PI);
        double width=angle*M_PI/180;
        int left=0,best=0;
        for(int right=0;right<(int)angles.size();++right){
            while(angles[right]-angles[left]>width+1e-12)++left;
            best=max(best,min(original,right-left+1));
        }
        return best+same;
    }
};
